(window.BSKQ=window.BSKQ||[]).push({id:'bs-nec',key:'nec',title:'1099-NEC Checker 2026',
inputs:[{id:'amt',label:'Total paid to this person or business in 2026 ($)',ph:'2400',step:1},
{id:'what',label:'What was it for?',type:'select',def:'svc',opts:[['svc','Services (labor, design, repairs, consulting)'],['legal','Legal services from an attorney'],['rent','Rent for office, equipment or land'],['prize','Prizes, awards or other income'],['goods','Goods or merchandise only']]},
{id:'who',label:'Who did you pay?',type:'select',def:'ind',opts:[['ind','Individual or sole proprietor'],['llc','LLC or partnership (not taxed as a corporation)'],['corp','C corporation or S corporation'],['emp','My employee (on payroll)'],['gov','Government or tax-exempt organization']]},
{id:'how',label:'How did you pay?',type:'select',def:'chk',opts:[['chk','Check, cash, bank transfer (ACH) or Zelle'],['card','Credit card, debit card or payment app (PayPal, Venmo business, Square)']]},
{id:'biz',label:'Was it paid by your business?',type:'select',def:'y',opts:[['y','Yes, for my trade or business'],['n','No, a personal payment']]},
{id:'w9',label:'Do you have their Form W-9 with a taxpayer ID?',type:'select',def:'y',opts:[['y','Yes'],['n','No']]},
{id:'yr',label:'Year the payments were made',type:'select',def:'2026',opts:[['2026','2026 (forms due Feb 1, 2027)'],['2025','2025 (forms were due Feb 2, 2026)']]}],
demo:{amt:'2400',what:'svc',who:'ind',how:'chk',biz:'y',w9:'y',yr:'2026'},
calc:function(v,F){var a=v.amt;if(!(a>=0))return {hint:'Enter the total you paid this person or business during the year.'};
 var T=v.yr==='2025'?600:2000,due=v.yr==='2025'?'Feb 2, 2026':'Feb 1, 2027',form='No form needed',why='',c='g';
 if(v.biz==='n'){why='Personal payments (for your home or family) are not reported on Form 1099.'}
 else if(v.who==='emp'){form='Form W-2';c='b';why='Employees get a W-2 through payroll, not a 1099-NEC.'}
 else if(v.how==='card'){why='Card and payment-network payments are reported by the card company or payment processor on Form 1099-K, so you do not file a 1099 for them.'}
 else if(v.what==='goods'){why='Payments for goods or merchandise alone are not reportable on Form 1099-NEC or 1099-MISC.'}
 else if(v.who==='gov'){why='Payments to government agencies and tax-exempt organizations are generally not reported.'}
 else if(v.who==='corp'&&v.what!=='legal'){why='Payments to C and S corporations are generally exempt. The main exception is legal services from an attorney.'}
 else if(a<T){why='You paid '+F.money(a,0)+', which is under the '+F.money(T,0)+' threshold for payments made in '+v.yr+'.'+(v.yr==='2026'&&a>=600?' Under the old $600 rule this would have needed a form.':'')}
 else if(v.what==='rent'||v.what==='prize'){form='Form 1099-MISC';c='r';why=(v.what==='rent'?'Rent goes in box 1':'Prizes and awards go in box 3')+' of Form 1099-MISC because the total is '+F.money(a,0)+' (threshold '+F.money(T,0)+').'}
 else{form='Form 1099-NEC';c='r';why=(v.what==='legal'?'Legal fees to an attorney are reported in box 1 even if the law firm is a corporation. ':'')+'You paid '+F.money(a,0)+' for services to a non-employee, which meets the '+F.money(T,0)+' threshold.'}
 var need=/^Form 1099/.test(form),bw=need&&v.w9==='n';
 if(v.w9==='n'&&!need&&v.biz==='y'&&v.who!=='emp'&&v.how!=='card'&&v.what!=='goods'&&v.who!=='gov'&&v.who!=='corp')why+=' Get a W-9 now: if later payments push the yearly total to '+F.money(T,0)+' and you still have no taxpayer ID, you must withhold 24%.';
 var k=[['Form needed',form,c],['Due date',need?due:'—',need?'b':''],['Threshold for '+v.yr,F.money(T,0)],['Backup withholding',bw?'Withhold 24%':'Not required',bw?'w':'g']];
 var steps=need?[['1','Get the payee\'s W-9'],['2','Send copy B by '+due],['3','File with the IRS by '+due],['4','Check your state\'s rules']]:[['1','Keep the invoice and payment record'],['2','Watch the yearly total ('+F.money(T,0)+')'],['3','Get a W-9 before you pay']];
 var rules=[['Services (person, sole prop, LLC)','$2,000+','1099-NEC'],['Attorney fees (even a corp)','$2,000+','1099-NEC'],['Rent, prizes, other income','$2,000+','1099-MISC'],['Royalties','$10+','1099-MISC'],['C or S corporation','any','Usually none'],['Card or payment app','any','None (1099-K)'],['Goods only','any','None']];
 return {kpis:k,tables:[{title:'Next steps',head:['#','What to do'],rows:steps},{title:'2026 Form 1099 rules at a glance',head:['Payment','Threshold','Form'],rows:rules}],note:why+(need?' E-file through the IRS IRIS portal if you file 10 or more information returns in total.':'')+(bw?' With no taxpayer ID, withhold 24% from the payment that brings the yearly total to the threshold and from every later payment, and deposit it with the IRS. Once you file a form for this payee, next year\'s withholding starts from the first dollar.':'')+' Reporting thresholds only decide which forms get filed; the payee still reports all of the income. Estimate only, not tax advice.'}}});

(window.BSKQ=window.BSKQ||[]).push({id:'bs-dc',key:'dc',title:'Dependent Care FSA vs Child Care Credit Calculator 2026',
inputs:[{id:'fs',label:'Filing status',type:'select',def:'m',opts:[['s','Single or head of household'],['m','Married filing jointly']]},{id:'agi',label:'Adjusted gross income, AGI ($)',ph:'95000',step:1},{id:'kids',label:'Children under 13 (or dependents who can\'t care for themselves)',type:'select',def:'1',opts:[['1','One'],['2','Two or more']]},{id:'exp',label:'Child care costs for the year ($)',ph:'12000',step:1},{id:'fsa',label:'Dependent care FSA you plan to use ($, max 7,500)',def:'7500',step:1},{id:'rate',label:'Your federal tax bracket (%)',type:'select',def:'22',opts:[['10','10%'],['12','12%'],['22','22%'],['24','24%'],['32','32%'],['35','35%']]},{id:'st',label:'State income tax rate (%)',def:'5',step:0.1}],
demo:{fs:'m',agi:'95000',kids:'1',exp:'12000',fsa:'7500',rate:'22',st:'5'},
calc:function(v,F){var a=v.agi,e=v.exp;if(!(a>=0)||!(e>0))return {hint:'Enter your AGI and your child care costs.'};
 var j=v.fs==='m';
 function pct(x){var p=50-Math.ceil(Math.max(0,x-15000)/2000);p=Math.max(35,p);var t=j?150000:75000,s=j?4000:2000;if(x>t)p=Math.max(20,p-Math.ceil((x-t)/s));return Math.min(50,p)}
 var p=pct(a)/100,lim=v.kids==='2'?6000:3000;
 var fsa=Math.min(Math.max(0,v.fsa||0),7500,e);
 var fr=(+v.rate||22)/100,sr=(v.st||0)/100;
 var fsaSave=fsa*(fr+0.0765+sr);
 var left=Math.max(0,Math.min(lim-fsa,e-fsa)),cr1=left*p;
 var crOnly=Math.min(lim,e)*p;
 var both=fsaSave+cr1;
 var best=both>=crOnly?'Use the FSA (plus any credit left)':'Skip the FSA, take the credit';
 var k=[['Best option',best,'g'],['FSA + credit savings',F.money(both,0),both>=crOnly?'g':''],['Credit only savings',F.money(crOnly,0),both<crOnly?'g':''],['Your credit rate',Math.round(p*100)+'%'],['Difference',F.money(Math.abs(both-crOnly),0)]];
 var rows=[['Child care costs',F.money(e,0),F.money(e,0)],['Paid through the FSA (pre-tax)',F.money(fsa,0),'$0'],['Tax saved on FSA money','≈'+F.money(fsaSave,0)+' (federal '+Math.round(fr*100)+'% + FICA 7.65% + state)','$0'],['Expenses left for the credit',F.money(left,0),F.money(Math.min(lim,e),0)],['Credit at '+Math.round(p*100)+'%',F.money(cr1,0),F.money(crOnly,0)],['Total tax saved',F.money(both,0),F.money(crOnly,0)]];
 var sched=[['$15,000 or less','50%'],['$15,001 - $43,000','49% down to 36% (1 point per $2,000)'],['$43,001 - '+(j?'$150,000':'$75,000'),'35%'],[j?'Over $150,000':'Over $75,000','down 1 point per '+(j?'$4,000':'$2,000')+' to 20%']];
 return {kpis:k,tables:[{title:'Side by side',head:['','FSA + credit','Credit only'],rows:rows},{title:'2026 child and dependent care credit rate by AGI',head:['AGI','Credit rate'],rows:sched}],
 note:'2026 rules: dependent care FSA limit $7,500 per household ($3,750 married filing separately); credit on up to $3,000 of costs for one child or $6,000 for two or more, reduced dollar for dollar by FSA money. The credit is nonrefundable, so it can\'t be more than your federal income tax. FSA money is use-it-or-lose-it. Estimate only, not tax advice.'}}});

(window.BSKQ=window.BSKQ||[]).push({id:'bs-ta',key:'ta',title:'Trump Account Calculator',
inputs:[{id:'by',label:'Child\'s birth year',ph:'2026',step:1},{id:'pilot',label:'$1,000 Treasury pilot deposit',type:'select',def:'1',opts:[['1','Yes (US citizen born 2025-2028)'],['0','No']]},{id:'fam',label:'Family contributions per year ($)',def:'1000',step:1},{id:'emp',label:'Employer contributions per year ($, up to 2,500)',def:'0',step:1},{id:'oth',label:'Other contributions per year, e.g. grandparents ($)',def:'0',step:1},{id:'ret',label:'Expected yearly return before fees (%)',def:'7',step:0.1},{id:'fee',label:'Fund fees (%, max 0.10)',def:'0.05',step:0.01}],
demo:{by:'2026',pilot:'1',fam:'1000',emp:'0',oth:'500',ret:'7',fee:'0.05'},
calc:function(v,F){var by=Math.round(v.by);if(!(by>=2008&&by<=2040))return {hint:'Enter the child\'s birth year (for example 2026).'};
 var start=2026,end=by+17;if(end<start)return {hint:'The growth period ends in the year the child turns 17, so this child is too old.'};
 var emp=Math.min(v.emp||0,2500),fam=v.fam||0,oth=v.oth||0,yr=fam+emp+oth,capped=Math.min(yr,5000),cut=yr-capped;
 var g=((v.ret||0)-(Math.min(v.fee||0,0.1)))/100,bal=0,ctb=0,rows=[];
 var pil=(+v.pilot===1&&by>=2025&&by<=2028)?1000:0;
 for(var y=start;y<=end;y++){var add=capped*(y===start?0.5:1);if(y===start){bal+=pil;}bal=bal*(1+g)+add*(1+g/2);ctb+=add;var age=y-by;if(y===start||age%3===0||y===end)rows.push([y+'',age<0?'-':age+'',F.money(ctb+(y>=start?pil:0),0),F.money(bal,0)]);}
 var tot=ctb+pil,earn=bal-tot;
 var k=[['Estimated balance at 18',F.money(bal,0),'g'],['Total put in',F.money(tot,0)],['Growth',F.money(earn,0),'g'],['Yearly contributions used',F.money(capped,0)]];
 if(pil)k.push(['Treasury pilot deposit',F.money(pil,0),'g']);
 if(cut>0)k.push(['Over the $5,000 yearly limit',F.money(cut,0),'w']);
 if(+v.pilot===1&&!pil)k.push(['Pilot deposit','Not eligible (born outside 2025-2028)','w']);
 return {kpis:k,tables:[{title:'Projected growth (contributions start July 4, 2026)',head:['Year','Age','Put in so far','Balance'],rows:rows},{title:'Key Trump Account rules',head:['Rule','Amount or limit'],rows:[['Treasury pilot deposit','$1,000, US citizens born 2025-2028'],['Yearly contribution limit','$5,000 (2026-2027, then inflation-adjusted)'],['Employer contribution','Up to $2,500 per employee, tax-free, counts toward $5,000'],['Investments','Low-cost US stock index fund, fees 0.1% or less'],['Withdrawals','Not before the year the child turns 18'],['After 18','Follows traditional IRA rules']]}],
 note:'Projection only: returns are not guaranteed and stock funds can lose value. Assumes half a year of contributions in 2026 and a steady return each year. Family contributions are not tax-deductible; growth is tax-deferred. Charitable and government deposits for groups of children (such as large pledges) are not counted. Estimate only, not financial advice.'}}});

(window.BSKQ=window.BSKQ||[]).push({id:'bs-salt',key:'salt',title:'SALT Deduction Cap Calculator 2026',
inputs:[{id:'fs',label:'Filing status',type:'select',def:'s',opts:[['s','Single'],['h','Head of household'],['m','Married filing jointly'],['ms','Married filing separately']]},{id:'magi',label:'Modified adjusted gross income, MAGI ($)',ph:'180000',step:1},{id:'inc',label:'State and local income tax paid, or sales tax if you choose it ($)',def:'0',step:1},{id:'prop',label:'Property tax on your home and car ($)',def:'0',step:1},{id:'mort',label:'Mortgage interest ($)',def:'0',step:1},{id:'char',label:'Charitable gifts and other itemized deductions ($)',def:'0',step:1},{id:'rate',label:'Your federal tax bracket (%)',type:'select',def:'24',opts:[['10','10%'],['12','12%'],['22','22%'],['24','24%'],['32','32%'],['35','35%'],['37','37%']]}],
demo:{fs:'m',magi:'260000',inc:'14800',prop:'9600',mort:'16500',char:'3000',rate:'24'},
calc:function(v,F){var m=v.magi;if(!(m>=0)||(!v.inc&&!v.prop))return {hint:'Enter your MAGI and the state/local and property taxes you paid.'};
 var ms=v.fs==='ms',cap=ms?20200:40400,thr=ms?252500:505000,flo=ms?5000:10000;
 var capA=Math.max(flo,cap-Math.max(0,m-thr)*0.3);
 var salt=(v.inc||0)+(v.prop||0),saltD=Math.min(salt,capA),lost=salt-saltD;
 var item=saltD+(v.mort||0)+(v.char||0);
 var std={s:16100,h:24150,m:32200,ms:16100}[v.fs];
 var best=Math.max(item,std),useI=item>std,r=(+v.rate||24)/100;
 var old10=Math.min(salt,ms?5000:10000),itemOld=old10+(v.mort||0)+(v.char||0);
 var gain=Math.max(0,best-Math.max(itemOld,std))*r;
 var k=[['Your 2026 SALT cap',F.money(capA,0),capA<cap?'w':''],['SALT you can deduct',F.money(saltD,0),'g'],['Itemized total',F.money(item,0)],['Standard deduction',F.money(std,0)],['Better choice',useI?'Itemize':'Standard deduction',useI?'g':''],['Tax saved vs the old $10,000 cap',F.money(gain,0),'g']];
 if(lost>0)k.push(['SALT over the cap (not deductible)',F.money(lost,0),'w']);
 var rows=[['State and local income/sales tax',F.money(v.inc||0,0)],['Property tax',F.money(v.prop||0,0)],['Total SALT paid',F.money(salt,0)],['Cap after income phase-down',F.money(capA,0)],['Deductible SALT',F.money(saltD,0)],['Mortgage interest',F.money(v.mort||0,0)],['Charity and other',F.money(v.char||0,0)],['Total itemized deductions',F.money(item,0)],['2026 standard deduction',F.money(std,0)]];
 var yrs=[['2025','$40,000','$500,000'],['2026','$40,400','$505,000'],['2027','$40,804','$510,050'],['2028','$41,212','$515,151'],['2029','$41,624','$520,302'],['2030 on','$10,000','none']];
 return {kpis:k,tables:[{title:'Your 2026 SALT and itemized deductions',head:['Item','Amount'],rows:rows},{title:'SALT cap by year (half for married filing separately)',head:['Tax year','Cap','Phase-down starts (MAGI)'],rows:yrs}],
 note:'The cap drops by 30% of your MAGI above the threshold but never below $10,000 ($5,000 married filing separately). SALT means state and local income tax (or general sales tax instead) plus real estate and personal property taxes; it does not include federal tax, gas tax or fees. You only benefit if your itemized total beats the standard deduction. Estimate only, not tax advice.'}}});

(window.BSKQ=window.BSKQ||[]).push({id:'bs-ab',key:'ab',title:'Airbnb Host Profit Calculator',
inputs:[{id:'nr',label:'Average nightly rate ($)',ph:'150',step:1},{id:'oc',label:'Occupancy (% of nights booked)',def:'65',step:1},{id:'st',label:'Average stay (nights)',def:'3',step:0.5},{id:'cf',label:'Cleaning fee you charge per stay ($)',def:'85',step:1},{id:'af',label:'Airbnb fee',type:'select',opts:[['15.5','Host-only fee 15.5%'],['3','Split fee 3% (if you still have it)']],def:'15.5'},{id:'cc',label:'Cleaning cost per turnover ($)',def:'75',step:1},{id:'sp',label:'Supplies per stay: toiletries, coffee, laundry ($)',def:'15',step:1},{id:'mg',label:'Rent or mortgage per month ($)',def:'1800',step:1},{id:'ut',label:'Utilities & internet per month ($)',def:'250',step:1},{id:'in',label:'Insurance per month ($)',def:'80',step:1},{id:'sw',label:'Software, permits & other per month ($)',def:'40',step:1},{id:'fu',label:'Furniture & linens replacement per year ($)',def:'1200',step:1},{id:'pm',label:'Co-host / manager (% of payout, 0 if none)',def:'0',step:1}],
demo:{nr:'150',oc:'65',st:'3',cf:'85',af:'15.5',cc:'75',sp:'15',mg:'1800',ut:'250',in:'80',sw:'40',fu:'1200',pm:'0'},
calc:function(v,F){var nr=v.nr,st=Math.max(1,v.st||1);if(!(nr>0))return {hint:'Enter your average nightly rate.'};
 function run(oc){var n=30.42*oc/100,s=n/st,rent=n*nr,cl=s*(v.cf||0),gross=rent+cl,fee=gross*(+v.af||0)/100,pay=gross-fee,pmf=pay*(v.pm||0)/100,var1=s*((v.cc||0)+(v.sp||0)),fix=(v.mg||0)+(v.ut||0)+(v.in||0)+(v.sw||0)+(v.fu||0)/12,pf=pay-pmf-var1-fix;return {n:n,s:s,rent:rent,cl:cl,gross:gross,fee:fee,pay:pay,pmf:pmf,var1:var1,fix:fix,pf:pf}}
 var r=run(v.oc||0),a=0,b=100;for(var i=0;i<50;i++){var m=(a+b)/2;if(run(m).pf>=0)b=m;else a=m}var be=run(100).pf<0?NaN:b;
 return {kpis:[['Profit per month',F.money(r.pf,0),r.pf>=0?'g':'w'],['Profit per year',F.money(r.pf*12,0)],['Airbnb fees per month',F.money(r.fee,0)],['Break-even occupancy',isFinite(be)?F.pct(be,0):'Not reachable','w']],
 tables:[{title:'Monthly breakdown',head:['Item','Per month'],rows:[['Nights booked',r.n.toFixed(1)+' nights'],['Stays',r.s.toFixed(1)],['Nightly revenue',F.money(r.rent,0)],['Cleaning fees charged',F.money(r.cl,0)],['Airbnb fee ('+F.pct(+v.af||0,1)+')','-'+F.money(r.fee,0)],['Your payout',F.money(r.pay,0)],['Co-host / manager','-'+F.money(r.pmf,0)],['Cleaning & supplies','-'+F.money(r.var1,0)],['Rent/mortgage, utilities, insurance, other','-'+F.money(r.fix,0)],['Profit before income tax',F.money(r.pf,0)]]},
 {title:'Profit at other occupancy rates',head:['Occupancy','Profit per month'],rows:[40,50,60,70,80].map(function(o){return [F.pct(o,0),F.money(run(o).pf,0)]})}],
 note:'Airbnb\'s host-only fee is charged on the booking subtotal (nightly rate plus cleaning and other fees you set). Occupancy tax collected by Airbnb is not included. Profit is before income tax; depreciation and other deductions can lower your taxes. Check local short-term rental rules and permits. Estimate only.'}}});

(window.BSKQ=window.BSKQ||[]).push({id:'bs-gd',key:'gd',title:'Gig Driver Real Earnings Calculator',
inputs:[{id:'py',label:'Weekly payouts incl. tips ($)',ph:'900',step:1},{id:'hr',label:'Hours online per week (incl. waiting)',def:'35',step:0.5},{id:'mi',label:'Miles driven for work per week',def:'650',step:1},{id:'mpg',label:'Car fuel economy (mpg)',def:'28',step:0.5},{id:'gp',label:'Gas price ($ per gallon)',def:'3.40',step:0.01},{id:'mt',label:'Maintenance & tires ($ per mile)',def:'0.10',step:0.01},{id:'dp',label:'Car wear & value lost ($ per mile)',def:'0.15',step:0.01},{id:'ph',label:'Phone & data for work per month ($)',def:'50',step:1},{id:'ins',label:'Extra rideshare insurance per month ($)',def:'30',step:1},{id:'it',label:'Your income tax bracket (%)',def:'12',step:1},{id:'rt',label:'IRS mileage rate (cents per mile)',def:'76',step:0.1}],
demo:{py:'900',hr:'35',mi:'650',mpg:'28',gp:'3.40',mt:'0.10',dp:'0.15',ph:'50',ins:'30',it:'12',rt:'76'},
calc:function(v,F){var py=v.py,h=v.hr;if(!(py>0)||!(h>0)||!(v.mpg>0))return {hint:'Enter your weekly payouts, hours online and fuel economy.'};
 var mi=v.mi||0,gas=mi/v.mpg*(v.gp||0),mt=mi*(v.mt||0),dp=mi*(v.dp||0),fix=((v.ph||0)+(v.ins||0))*12/52,cost=gas+mt+dp+fix,net=py-cost;
 var rt=(v.rt||0)/100,ded=mi*rt+(v.ph||0)*12/52,tp=Math.max(0,py-ded),se=tp*0.9235*0.153,inc=Math.max(0,tp-se/2)*(v.it||0)/100,tax=se+inc,take=net-tax;
 return {kpis:[['Real pay per hour',F.money(take/h,2),'g'],['Payout per hour (before costs)',F.money(py/h,2)],['Take-home per week',F.money(take,0)],['Set aside for taxes',F.money(tax,0)+' / week','w']],
 tables:[{title:'Where your payout goes (per week)',head:['Item','Amount'],rows:[['Payouts incl. tips',F.money(py,2)],['Gas',' -'+F.money(gas,2)],['Maintenance & tires',' -'+F.money(mt,2)],['Car wear & value lost',' -'+F.money(dp,2)],['Phone & insurance',' -'+F.money(fix,2)],['Self-employment tax (est.)',' -'+F.money(se,2)],['Income tax (est.)',' -'+F.money(inc,2)],['Take-home',F.money(take,2)]]},
 {title:'Per mile and per year',head:['Measure','Amount'],rows:[['Payout per mile',F.money(mi?py/mi:0,2)],['Real cost per mile',F.money(mi?(gas+mt+dp)/mi:0,3)],['IRS mileage deduction ('+(v.rt||0)+'¢ × miles)',F.money(mi*rt,0)+' / week'],['Take-home per year (52 weeks)',F.money(take*52,0)]]}],
 note:'Taxes use the IRS standard mileage rate you enter (2026: 76 cents per business mile from July 1; 72.5 cents for January to June), which already covers gas, maintenance, insurance and wear, so you can\'t deduct those separately if you use it. Self-employment tax is 15.3% on 92.35% of profit. Income tax is a rough estimate at your bracket; state tax is not included. Keep a mileage log. Estimate only, not tax advice.'}}});

(window.BSKQ=window.BSKQ||[]).push({id:'bs-lw',key:'lw',title:'Lawn Mowing Price Calculator',
inputs:[{id:'sf',label:'Lawn area to mow (square feet)',ph:'8000',step:100},{id:'mw',label:'Mower',type:'select',opts:[['10000','21-inch push mower (~10,000 sq ft/hr)'],['20000','36–48 inch walk-behind (~20,000 sq ft/hr)'],['40000','52–60 inch zero-turn (~40,000 sq ft/hr)']],def:'20000'},{id:'tr',label:'Trim, edge & blow (minutes per visit)',def:'15',step:1},{id:'tv',label:'Drive time to the job (minutes)',def:'10',step:1},{id:'cr',label:'Crew size',def:'1',step:1},{id:'wg',label:'Pay per worker per hour ($)',def:'18',step:0.5},{id:'eq',label:'Fuel & equipment cost per hour ($)',def:'12',step:0.5},{id:'oh',label:'Overhead: insurance, truck, ads (% of price)',def:'15',step:1},{id:'mg',label:'Profit margin (% of price)',def:'20',step:1},{id:'mn',label:'Minimum charge per visit ($)',def:'40',step:1},{id:'sn',label:'Visits per season',def:'28',step:1}],
demo:{sf:'8000',mw:'20000',tr:'15',tv:'10',cr:'1',wg:'18',eq:'12',oh:'15',mg:'20',mn:'40',sn:'28'},
calc:function(v,F){var sf=v.sf;if(!(sf>0))return {hint:'Enter the lawn area in square feet (an acre is 43,560 sq ft).'};
 var cr=Math.max(1,v.cr||1),mw=+v.mw||20000,mow=sf/mw,trim=(v.tr||0)/60,trav=(v.tv||0)/60,ph=mow+trim+trav,onsite=(mow+trim)/cr;
 var labor=ph*(v.wg||0)*1.12,eq=(onsite+trav)*(v.eq||0),cost=labor+eq,k=1-((v.oh||0)+(v.mg||0))/100;if(k<=0.05)return {hint:'Overhead plus margin must be well under 100%.'};
 var raw=cost/k,price=Math.max(v.mn||0,Math.ceil(raw/5)*5),hr=price/((onsite+trav)||1);
