var F={cp:['pm-cost','pm-price'],cm:['pm-cost','pm-margin'],ck:['pm-cost','pm-markup'],pm:['pm-price','pm-margin']};
function show(){var m=$('pm-mode').value;['pm-cost','pm-price','pm-margin','pm-markup'].forEach(function(id){$(id).closest('div').style.display=F[m].indexOf(id)>=0?'':'none'});calc()}
function calc(){var m=$('pm-mode').value,c=num($('pm-cost').value),p=num($('pm-price').value),g=num($('pm-margin').value),k=num($('pm-markup').value),err='';
 if(m==='cm'){if(g>=100)err='Margin must be below 100%.';else p=c/(1-g/100)}
 else if(m==='ck'){p=c*(1+k/100)}
 else if(m==='pm'){if(g>=100)err='Margin must be below 100%.';else c=p*(1-g/100)}
 var o=$('pm-out');
 if(err){o.innerHTML='<p class="pm-err">'+err+'</p>';return}
 if(!isFinite(c)||!isFinite(p)){o.innerHTML='<p class="pm-hint">Enter the two values above to see your results.</p>';return}
 var pr=p-c,mg=p?pr/p*100:0,mk=c?pr/c*100:0;
 o.innerHTML='<div class="pm-kpi"><div><span>Cost</span><b>'+money(c)+'</b></div><div><span>Selling price</span><b>'+money(p)+'</b></div><div class="'+(pr<0?'d':'g')+'"><span>Gross profit</span><b>'+money(pr)+'</b></div><div><span>Gross margin</span><b>'+(p?pct(mg):'n/a')+'</b></div><div><span>Markup</span><b>'+(c?pct(mk):'n/a')+'</b></div></div>'+
 '<p class="pm-ex">Margin = profit &divide; price = '+money(pr)+' &divide; '+money(p)+(p?' = '+pct(mg):'')+'. Markup = profit &divide; cost = '+money(pr)+' &divide; '+money(c)+(c?' = '+pct(mk):'')+'.</p>';
}
$('pm-mode').addEventListener('change',show);
['pm-cost','pm-price','pm-margin','pm-markup'].forEach(function(id){$(id).addEventListener('input',calc)});
$('pm-reset').onclick=function(){['pm-cost','pm-price','pm-margin','pm-markup'].forEach(function(id){$(id).value=''});calc()};
show();
})();

sty:
#bs-pm{--n:#12355B;--g:#1D7A4F;--m:#E8F3EC;--b:#d5dde6;font-family:inherit;margin:2rem 0}
#bs-pm *{box-sizing:border-box}
#bs-pm .pm-card{border:1px solid var(--b);border-radius:14px;background:#fff;padding:20px;box-shadow:0 2px 10px rgba(18,53,91,.06)}
#bs-pm .pm-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-bottom:14px}
#bs-pm label{display:block;font-size:.8rem;font-weight:600;color:#4a5a6a;margin-bottom:4px}
#bs-pm input,#bs-pm select{width:100%;padding:9px 10px;border:1px solid var(--b);border-radius:8px;font:inherit;font-size:.95rem;background:#fffdf3}
#bs-pm input:focus,#bs-pm select:focus{outline:2px solid var(--g);border-color:var(--g)}
#bs-pm .pm-kpi{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px}
#bs-pm .pm-kpi div{background:#f3f6f9;border-radius:10px;padding:12px}
#bs-pm .pm-kpi div.g{background:var(--m)}#bs-pm .pm-kpi div.d{background:#fde4e4}
#bs-pm .pm-kpi b{display:block;font-size:1.2rem;color:var(--n)}
#bs-pm .pm-kpi span{font-size:.72rem;color:#4a5a6a;font-weight:600;text-transform:uppercase;letter-spacing:.03em}
#bs-pm .pm-ex,#bs-pm .pm-hint{font-size:.85rem;color:#5b6876;margin:12px 0 0}
#bs-pm .pm-err{color:#a12626;font-weight:600}
#bs-pm .pm-btn{border:1px solid var(--n);background:#fff;color:var(--n);border-radius:9px;padding:8px 14px;font:inherit;font-size:.85rem;font-weight:600;cursor:pointer;margin-top:12px}

scr:
(window.BSKQ=window.BSKQ||[]).push({id:'bs-cf',key:'cf',title:'13-Week Cash Flow Forecast Calculator',
inputs:[{id:'ob',label:'Bank balance today ($)',ph:'15000',step:1},{id:'rc',label:'Customer receipts per week ($)',def:'7800',step:1},{id:'gr',label:'Weekly change in receipts (%)',def:'0',step:0.1},{id:'ar',label:'Overdue invoices you expect to collect ($)',def:'5000',step:1},{id:'aw',label:'...collected in week #',def:'10',step:1},{id:'py',label:'Payroll per pay run ($)',def:'8500',step:1},{id:'pf',label:'Payroll frequency',type:'select',opts:[['2','Every 2 weeks'],['1','Every week']],def:'2'},{id:'rt',label:'Rent & loan payments per month ($)',def:'3200',step:1},{id:'op',label:'Other costs per week: suppliers, software, fuel ($)',def:'2400',step:1},{id:'tx',label:'Tax or other one-off payment ($)',def:'6500',step:1},{id:'tw',label:'...paid in week #',def:'8',step:1},{id:'bf',label:'Minimum cash buffer ($)',def:'8000',step:1}],
demo:{ob:'15000',rc:'7800',gr:'0',ar:'5000',aw:'10',py:'8500',pf:'2',rt:'3200',op:'2400',tx:'6500',tw:'8',bf:'8000'},
calc:function(v,F){if(!(v.ob>=0)||v.ob===''||isNaN(v.ob))return {hint:'Enter your bank balance today to start the 13-week forecast.'};
 var bal=+v.ob||0,rows=[],low=1e18,lowW=0,below=0,tr=0,tp=0,pf=(+v.pf||2),g=(+v.gr||0)/100,first=0;
 for(var w=1;w<=13;w++){var rec=(+v.rc||0)*Math.pow(1+g,w-1);if(w===Math.round(+v.aw||0))rec+=(+v.ar||0);
  var pay=(+v.op||0);var pr=((w-1)%pf===0)?(+v.py||0):0;var rent=(w%4===1)?(+v.rt||0):0;var one=(w===Math.round(+v.tw||0))?(+v.tx||0):0;
  var out=pay+pr+rent+one,net=rec-out,open=bal;bal+=net;tr+=rec;tp+=out;
  if(bal<low){low=bal;lowW=w}if(bal<(+v.bf||0)){below++;if(!first)first=w}
  rows.push(['Week '+w,F.money(open,0),F.money(rec,0),'-'+F.money(out,0),(net<0?'-':'')+F.money(Math.abs(net),0),(bal<(+v.bf||0)?'⚠ ':'')+F.money(bal,0)])}
 var st=below?'Below buffer in '+below+' week'+(below>1?'s':''):'Never below buffer';
 return {kpis:[['Lowest balance',F.money(low,0)+' (week '+lowW+')',low<(+v.bf||0)?'w':'g'],['Cash in week 13',F.money(bal,0)],['Total in / out',F.money(tr,0)+' / '+F.money(tp,0)],['Buffer check',st,below?'w':'g']],
 tables:[{title:'Your 13-week cash flow forecast',head:['Week','Opening cash','Cash in','Cash out','Net','Closing cash'],rows:rows}],
 note:(below?'Cash drops below your '+F.money(+v.bf||0,0)+' buffer first in week '+first+'. Act before then: chase overdue invoices, ask key customers for faster payment, move a supplier payment, or arrange a line of credit now while your numbers look fine. ':'Your cash stays above your buffer for all 13 weeks. ')+'Rent and loan payments are placed in weeks 1, 5, 9 and 13; payroll starts in week 1. Download the Excel template on this page to enter exact amounts week by week. Planning estimate only.'}}});
